import {createHash} from 'node:crypto';
import {syntheticSchoolPdf,syntheticSchoolHash} from './family-schooling-synthetic.js';
import {FAMILY_REQUEST_VERSION,FAMILY_SELF_SUBMIT,FAMILY_REVIEW_WRITE,familyRequestSerialized} from '../../assets/native-family-request-model.js';
export const uid=n=>'10000000-0000-4000-8000-'+String(n).padStart(12,'0');
export const key=uid(90),requestId=uid(91),scope={tenantId:uid(1),membershipId:uid(2)};
export const session={id:uid(3),email:'family-synthetic@example.test',version:2,releaseSha:'a'.repeat(40)};
export const principal=(caps=FAMILY_SELF_SUBMIT)=>({user:{email:session.email},tenant:{source:'membership',id:scope.tenantId,membershipId:scope.membershipId,certifiedReleaseSha:session.releaseSha,effectiveCapabilities:[...caps]}});
export const child=()=>({kind:'child',definition:{familyName:'Hija exclusivamente sintética',birthDate:'2015-06-05',dni:null,validFrom:null,validTo:null},document:null});
export const school=()=>({kind:'schooling',definition:{familyRef:{kind:'own',id:uid(10)},identityToken:'b'.repeat(64),expectedCertificateId:null,institution:'Escuela exclusivamente sintética',educationLevel:null,course:null,schoolYear:2026,issuedOn:'2026-02-01',presentedOn:'2026-03-01',expiresOn:null,evidenceMode:'pdf',paperReference:null},document:{filename:'certificado-sintetico.pdf',sha256:syntheticSchoolHash,contentBase64:syntheticSchoolPdf.toString('base64')}});
export const command=patch=>({version:FAMILY_REQUEST_VERSION,command:'submit',requestId:null,expectedVersion:0,subjectVersion:'c'.repeat(64),payload:child(),reason:'Presentación familiar exclusivamente sintética',reviewConfirmed:true,...patch});
export const review=patch=>command({command:'accept',requestId,expectedVersion:1,subjectVersion:null,payload:null,reason:'Revisión administrativa exclusivamente sintética',...patch});
export const bodyHash=b=>createHash('sha256').update(familyRequestSerialized(b)).digest('hex');
export const receipt=(body=command(),patch={})=>({version:'native-family-request-receipt.v1',scope:{...scope},key,requestId:body.requestId??requestId,requestVersion:body.expectedVersion+1,requestKind:body.payload?.kind??'child',command:body.command,state:{submit:'submitted',resubmit:'submitted',request_correction:'correction_requested',accept:'accepted',reject:'rejected'}[body.command],bodySha256:bodyHash(body),recordedAt:'2026-10-16T12:00:00.000000Z',replayed:false,administrativeRecord:body.command==='accept'?{kind:'child',familyRef:{kind:'own',id:uid(10)},certificateId:null}:null,payrollModified:false,benefitGranted:false,...patch});
export const list=(view='self',patch={})=>({version:'native-family-requests.v1',view,scope:{...scope},state:view==='self'?'native':'ready',subject:view==='self'?{legajo:'5001',employeeName:'Persona exclusivamente sintética',subjectVersion:'c'.repeat(64)}:null,families:[],requests:[],total:0,complete:true,canSubmit:view==='self',page:{size:50,offset:0,returned:0,nextCursor:null,snapshotVersion:'d'.repeat(64),contextVersion:'e'.repeat(64)},...patch});
export const detail=(view='self',patch={})=>({version:'native-family-request-detail.v1',view,scope:{...scope},id:requestId,kind:'child',state:'submitted',requestVersion:1,subject:{legajo:'5001',employeeName:'Persona exclusivamente sintética'},subjectVersion:'c'.repeat(64),payload:child(),events:[{id:uid(100),requestVersion:1,command:'submit',state:'submitted',reason:'Presentación familiar exclusivamente sintética',actorLabel:'Persona exclusivamente sintética',recordedAt:'2026-10-16T12:00:00.000000Z',document:null}],canResubmit:false,canReview:view==='review',...patch});
export const document=patch=>({version:'native-family-request-document.v1',requestId,requestVersion:1,filename:'certificado-sintetico.pdf',sha256:syntheticSchoolHash,byteLength:syntheticSchoolPdf.length,contentBase64:syntheticSchoolPdf.toString('base64'),...patch});
export {syntheticSchoolPdf,syntheticSchoolHash,FAMILY_REVIEW_WRITE};
